// Night Sky positional astronomy, design_v1 section 11.1 (T1..T7). Known answers from astropy
// (ICRS -> AltAz, pressure 0), regenerated by tools/night-sky/astropy-known-answers.py into
// tests/fixtures/night-sky-astropy.json; the spec table is also hard-coded below and must agree.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { raDecToAltAz, skyMatrix, apply3, unitVector, worldToAltAz, gmstDeg, localToUtcMs, SIDEREAL_DAY_S, precessionMatrix, precessRaDec, centuriesSinceJ2000 } from "../public/night-sky/ns-astro.js";

const FX = JSON.parse(readFileSync(new URL("./fixtures/night-sky-astropy.json", import.meta.url), "utf8"));
const LAT = 38.39, LON = -86.93, TOL = 0.05;
const STAR = { Polaris: [2.52975, 89.264109], Sirius: [6.752481, -16.716116], Vega: [18.61564, 38.783692], Betelgeuse: [5.919529, 7.407063] };
const SPEC = {
  T1: { utc: "2026-12-21T03:00:00Z", rows: { Polaris: [39.009, 359.992], Sirius: [15.317, 126.734], Vega: [0.600, 322.309], Betelgeuse: [41.545, 118.829] } },
  T2: { utc: "2026-06-21T03:00:00Z", rows: { Polaris: [37.762, 0.017], Sirius: [-38.185, 278.948], Vega: [49.879, 72.511], Betelgeuse: [-29.987, 310.332] } },
};
const azDiff = (a, b) => Math.abs(((a - b + 540) % 360) - 180);
const report = [];

for (const tag of ["T1", "T2"]) {
  test(`${tag}: alt/az within ${TOL} deg of astropy (formula path and sky-matrix path), precession on`, () => {
    const t = Date.parse(SPEC[tag].utc);
    for (const [name, [alt, az]] of Object.entries(SPEC[tag].rows)) {
      const fx = FX.stars[tag].rows[name];
      assert.ok(Math.abs(fx.alt - alt) < 0.001 && azDiff(fx.az, az) < 0.001, `fixture and spec table disagree for ${name}`);
      const [ra, dec] = STAR[name];
      const f = raDecToAltAz(ra, dec, t, LAT, LON);
      const m = worldToAltAz(apply3(skyMatrix(t, LAT, LON), unitVector(ra * 15, dec)));
      for (const [label, got] of [["formula", f], ["matrix", m]]) {
        const dAlt = Math.abs(got.alt - fx.alt), dAz = azDiff(got.az, fx.az);
        if (label === "formula") report.push(`${tag} ${name.padEnd(10)} alt ${got.alt.toFixed(3)} (astropy ${fx.alt.toFixed(3)}, d ${dAlt.toFixed(4)})  az ${got.az.toFixed(3)} (astropy ${fx.az.toFixed(3)}, d ${dAz.toFixed(4)})`);
        assert.ok(dAlt < TOL, `${tag} ${name} ${label} alt ${got.alt} vs ${fx.alt}`);
        // azimuth is ill-defined right at the pole; Polaris az is compared on the sky (times cos alt)
        assert.ok(dAz * Math.cos(fx.alt * Math.PI / 180) < TOL, `${tag} ${name} ${label} az ${got.az} vs ${fx.az}`);
      }
    }
  });
}

test("T1: GMST matches astropy 8h 58m 48.66s within 1 s of time", () => {
  const g = gmstDeg(Date.parse("2026-12-21T03:00:00Z")) / 15;
  assert.ok(Math.abs(g - FX.stars.T1.gmst_h) * 3600 < 1, `${g} vs ${FX.stars.T1.gmst_h}`);
  assert.ok(Math.abs(FX.stars.T1.gmst_h - (8 + 58 / 60 + 48.66 / 3600)) * 3600 < 0.05);
});

test("T1: with precession OFF, Sirius is off by at least 0.1 deg (the matrix is doing something)", () => {
  const t = Date.parse(SPEC.T1.utc); const fx = FX.stars.T1.rows.Sirius;
  const off = raDecToAltAz(...STAR.Sirius, t, LAT, LON, { precession: false });
  const err = Math.hypot(off.alt - fx.alt, azDiff(off.az, fx.az) * Math.cos(fx.alt * Math.PI / 180));
  report.push(`T1 Sirius precession OFF error ${err.toFixed(3)} deg (spec measured 0.21)`);
  assert.ok(err >= 0.1, String(err));
});

test("precession matrix equals the scalar Meeus 21.4 form", () => {
  const T = centuriesSinceJ2000(Date.parse("2026-12-21T03:00:00Z"));
  for (const [ra, dec] of [[37.9, 89.26], [101.3, -16.7], [279.2, 38.8], [0, 0], [200, -70]]) {
    const v = apply3(precessionMatrix(T), unitVector(ra, dec));
    const s = precessRaDec(ra, dec, T), w = unitVector(s.raDeg, s.decDeg);
    assert.ok(Math.hypot(v[0] - w[0], v[1] - w[1], v[2] - w[2]) < 1e-9);
  }
});

test("T3: Polaris over a year at Jasper (hourly): alt within lat +- 0.8, az within 1 deg of north", () => {
  const t0 = Date.parse("2026-01-01T00:00:00Z");
  for (let h = 0; h < 8760; h++) {
    const p = raDecToAltAz(...STAR.Polaris, t0 + h * 3600e3, 38.3914, -86.9311);
    assert.ok(p.alt > 38.3914 - 0.8 && p.alt < 38.3914 + 0.8, String(p.alt));
    assert.ok(azDiff(p.az, 0) < 1.0, String(p.az));
  }
});

test("T4: one sidereal day returns a star within 0.01 deg; one solar day is about 0.9856 deg off", () => {
  const t = Date.parse("2026-12-21T03:00:00Z");
  const a = raDecToAltAz(...STAR.Betelgeuse, t, LAT, LON);
  const b = raDecToAltAz(...STAR.Betelgeuse, t + SIDEREAL_DAY_S * 1000, LAT, LON);
  const c = raDecToAltAz(...STAR.Betelgeuse, t + 86400e3, LAT, LON);
  assert.ok(Math.abs(a.alt - b.alt) < 0.01 && azDiff(a.az, b.az) < 0.01);
  const ha = (gmstDeg(t + 86400e3) - gmstDeg(t) + 360) % 360;
  assert.ok(Math.abs(ha - 0.9856) < 0.001, String(ha));
  assert.ok(Math.abs(a.alt - c.alt) > 0.1);
});

test("T5: circumpolar at 38.39 N; Alpha Centauri never rises; at Sydney it never sets", () => {
  const t0 = Date.parse("2026-12-21T00:00:00Z");
  for (let m = 0; m < 24 * 60; m += 10) {
    const t = t0 + m * 60e3;
    assert.ok(raDecToAltAz(3, 60, t, LAT, LON).alt > 0);
    assert.ok(raDecToAltAz(3, -60, t, LAT, LON).alt < 0);
    assert.ok(raDecToAltAz(14.66, -60.83, t, LAT, LON).alt < 0);
    assert.ok(raDecToAltAz(14.66, -60.83, t, -33.8688, 151.2093).alt > 0);
  }
});

test("T6: North Pole altitudes constant (= dec of date); at the equator Polaris stays within 0.75 deg of the horizon", () => {
  const t0 = Date.parse("2026-12-21T00:00:00Z");
  const T = centuriesSinceJ2000(t0);
  for (const [ra, dec] of [[5.9, 7.4], [18.6, 38.8], [2.53, 89.26]]) {
    const decDate = precessRaDec(ra * 15, dec, T).decDeg;
    for (let m = 0; m < 24 * 60; m += 30) assert.ok(Math.abs(raDecToAltAz(ra, dec, t0 + m * 60e3, 90, 0).alt - decDate) < 0.001);
  }
  for (let m = 0; m < 24 * 60; m += 10) assert.ok(Math.abs(raDecToAltAz(...STAR.Polaris, t0 + m * 60e3, 0, LON).alt) < 0.75);
});

test("T7: time zones, including the spring-forward gap and the repeated fall-back hour", () => {
  const z = "America/New_York";
  assert.equal(new Date(localToUtcMs(2026, 12, 20, 22, 0, z)).toISOString(), "2026-12-21T03:00:00.000Z");
  assert.equal(new Date(localToUtcMs(2026, 6, 20, 23, 0, z)).toISOString(), "2026-06-21T03:00:00.000Z");
  assert.equal(new Date(localToUtcMs(2027, 3, 14, 2, 30, z)).toISOString(), "2027-03-14T07:30:00.000Z"); // 03:30 EDT
  assert.equal(new Date(localToUtcMs(2026, 11, 1, 1, 30, z)).toISOString(), "2026-11-01T05:30:00.000Z"); // first 01:30 = EDT
});

test.after(() => console.log("\n" + report.join("\n")));
